DO $$ DECLARE r record; BEGIN FOR r IN SELECT customer_id, channel FROM public.erplain_sales_customers LOOP IF public.customer_channel(r.customer_id) IS DISTINCT FROM (CASE WHEN r.channel IN ('B2B','OEM') THEN r.channel ELSE 'B2C' END) THEN RAISE EXCEPTION 'Classement commun incohérent'; END IF; END LOOP; IF public.customer_channel('__classification_missing_test__') <> 'B2C' THEN RAISE EXCEPTION 'Canal par défaut incohérent'; END IF; END; $$;